WITH paid AS (
  SELECT customer_id, SUM(amount) AS total FROM payments GROUP BY customer_id
)
SELECT * FROM paid ORDER BY total DESC LIMIT 10;

CREATE TEMP TABLE suspects AS
SELECT DISTINCT user_id FROM downloads WHERE build_id = 412;
SELECT COUNT(*) FROM suspects;

WITH recent AS MATERIALIZED (
  SELECT * FROM downloads WHERE at >= '2026-03-01'
)
SELECT ip, COUNT(*) FROM recent GROUP BY ip;
